SELECT p.id, p.symbol, p.closed_at, p.exit_price, p.stop_loss, p.take_profit, (SELECT MIN(c.open_time) FROM candle c WHERE c.symbol = p.symbol AND c.interval_code = '1m' AND c.open_time BETWEEN p.closed_at - INTERVAL 1 MINUTE AND p.closed_at + INTERVAL 120 MINUTE AND c.high_price >= p.take_profit) AS first_tp_touch_ksa, (SELECT MIN(c.open_time) FROM candle c WHERE c.symbol = p.symbol AND c.interval_code = '1m' AND c.open_time BETWEEN p.closed_at - INTERVAL 1 MINUTE AND p.closed_at + INTERVAL 120 MINUTE AND c.low_price <= p.stop_loss) AS first_sl_touch_ksa, (SELECT MAX(c.high_price) FROM candle c WHERE c.symbol = p.symbol AND c.interval_code = '1m' AND c.open_time BETWEEN p.closed_at AND p.closed_at + INTERVAL 60 MINUTE) AS max_high_60m, (SELECT MIN(c.low_price) FROM candle c WHERE c.symbol = p.symbol AND c.interval_code = '1m' AND c.open_time BETWEEN p.closed_at AND p.closed_at + INTERVAL 60 MINUTE) AS min_low_60m FROM paper_position p WHERE p.id IN (104,101,96,91,82,78) ORDER BY p.id